`timescale 1ns/1ps
// DTW tone-template matcher (docs/10 §6, R81 A-board fill).
//
// RETIRED (R83b, docs/10 s7a): retained un-instantiated -- not in any bit,
// no template ROM exists, tb_dtw was removed from the regression in 2026-10.
// Third classifier vote alongside Board B's F0 LUT and the NB fallback:
// template DTW over the per-frame (relative pitch, relative level) contour
// against 4 tone templates. Templates are GENERATED by
// tools/extract_templates_dtw.py -> dtw_templates.vh (tpl_rom case table;
// keep the .vh next to this file for TD include resolution). Features are
// mean-removed per utterance so templates encode the tone SHAPE and
// transfer across speakers.
//
// FSM (freeze -> verdict ~5k clocks = 200 us at 25 MHz):
//   S_CAP      96-frame capture, opens on first voiced, freezes UV_RESET
//              unvoiced after the last (needs >= 8 frames to evaluate)
//   S_DIV      2 x 16-cycle restoring division for the two means
//   S_RSM      32 output frames via Bresenham stride (no multiplier),
//              mean-removed, 2 clocks each
//   S_DTW      4 templates x 32 rows x 32 cols, 1 clock per cell,
//              cost = 2*|dp| + |dl| (contract §6 weighting, pitch 2x level),
//              D[i][j] = c + min(up, left, diag), rolling row pairs
//   S_DONE     verdict held until the next capture opens
module dtw_matcher #(
    parameter integer UV_RESET = 24
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        frame_valid,
    input  wire        voiced,
    input  wire [9:0]  pitch_q4,
    input  wire [7:0]  level,
    output reg  [2:0]  dtw_tone,        // 1..4
    output reg         dtw_ready        // verdict held for this utterance
);
    localparam [2:0] S_CAP = 3'd0, S_DIV = 3'd1, S_RSM = 3'd2,
                     S_DTW = 3'd3, S_DONE = 3'd4;

    reg [2:0]  st;
    reg        cap_active;
    reg [5:0]  uv_cnt;
    reg [6:0]  cap_cnt;
    reg [15:0] cap_mem [0:95];           // {pitch_q4[9:2], level}
    reg signed [13:0] p_sum;             // 96 x 127 max = 12192 (14b signed)
    reg [15:0] l_sum;

    // divider
    reg [4:0]  div_cnt;                  // 0..16
    reg [15:0] div_num;                  // dividend magnitude
    reg [7:0]  rem;                      // partial remainder (< divisor)
    reg [7:0]  rem_shift;                // combinational shifted rem
    reg [15:0] div_q;
    reg        div_level;                // 0: pitch, 1: level
    reg        div_neg;                  // dividend was negative
    reg signed [8:0]  mean_p;
    reg [7:0]  mean_l;

    // resample
    reg [5:0]  rs_j;
    wire [11:0] rs_prod = rs_j * cap_cnt;         // <= 31*96 = 2976
    wire [6:0]  rs_src_idx = rs_prod[11:5];       // >>5, <= 92
    reg signed [7:0] work_p [0:31];
    reg [7:0]  work_l [0:31];

    // DP
    reg [1:0]  tp_sel;
    reg [5:0]  row, col;
    reg signed [17:0] rowA [0:31];       // D[i-1][*]
    reg signed [17:0] rowB [0:31];       // D[i][*]
    reg        rowB_is_cur;              // which array is the current row
    reg signed [17:0] cur;               // D[i][j-1]
    reg signed [17:0] cost [0:3];
    reg [1:0]  best_tpl;
    reg signed [17:0] best_cost;

    // template ROM (generated case table, combinational)
    function [15:0] tpl_rom;
        input [6:0] addr;                // {tone[1:0], frame[5:0]}
        begin
            case (addr)
                `include "dtw_templates.vh"
                default: tpl_rom = 16'h8000;
            endcase
        end
    endfunction

    wire [15:0] tpl_v = tpl_rom({tp_sel, col[4:0]});
    wire signed [7:0] tpl_p = tpl_v[15:8];
    wire [7:0]  tpl_l = tpl_v[7:0];

    wire signed [7:0] wp = work_p[row[4:0]];
    wire [7:0]  wl = work_l[row[4:0]];
    wire signed [8:0] dp_d = wp - tpl_p;
    wire [8:0]  dp_abs = dp_d[8] ? (-dp_d) : dp_d;
    wire [8:0]  dl_abs = (wl > tpl_l) ? (wl - tpl_l) : (tpl_l - wl);
    wire signed [17:0] c_nxt = {2'b0, dp_abs, 1'b0}    // 2*|dp|
                             + {9'd0, dl_abs};         // |dl|

    // previous-row read with the toggle
    wire signed [17:0] prev_j   = rowB_is_cur ? rowA[col]   : rowB[col];
    wire signed [17:0] prev_jm1 = rowB_is_cur ? rowA[col-1] : rowB[col-1];
    wire signed [17:0] prev_0   = rowB_is_cur ? rowA[6'd0]  : rowB[6'd0];

    // DP cell value (combinational, 1 clock per cell)
    wire signed [17:0] d_cell =
        (row == 6'd0) ? (cur + c_nxt)                       // D[0][j-1]+c
        : (col == 6'd0) ? (prev_0 + c_nxt)                  // D[i-1][0]+c
        : (c_nxt + ((prev_j < cur)
                      ? ((prev_j < prev_jm1) ? prev_j : prev_jm1)
                      : ((cur < prev_jm1) ? cur : prev_jm1)));

    integer gi;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            st <= S_CAP; cap_active <= 1'b0; uv_cnt <= 6'd0;
            cap_cnt <= 7'd0; p_sum <= 14'sd0; l_sum <= 16'd0;
            div_cnt <= 5'd0; div_num <= 16'd0; rem <= 8'd0;
            rem_shift <= 8'd0; div_q <= 16'd0; div_level <= 1'b0;
            div_neg <= 1'b0;
            mean_p <= 9'sd0; mean_l <= 8'd0;
            rs_j <= 6'd0;
            tp_sel <= 2'd0; row <= 6'd0; col <= 6'd0;
            rowB_is_cur <= 1'b1; cur <= 18'sd0;
            best_tpl <= 2'd0; best_cost <= 18'sd131071;
            dtw_tone <= 3'd0; dtw_ready <= 1'b0;
            for (gi = 0; gi < 96; gi = gi + 1) cap_mem[gi] <= 16'd0;
            for (gi = 0; gi < 32; gi = gi + 1) begin
                work_p[gi] <= 8'sd0; work_l[gi] <= 8'd0;
                rowA[gi] <= 18'sd0; rowB[gi] <= 18'sd0;
            end
            cost[0] <= 18'sd0; cost[1] <= 18'sd0;
            cost[2] <= 18'sd0; cost[3] <= 18'sd0;
        end else begin
            // ================= S_CAP =================
            if (st == S_CAP) begin
                if (frame_valid) begin
                    if (voiced) begin
                        uv_cnt <= 6'd0;
                        if (!cap_active) begin
                            cap_active <= 1'b1;
                            cap_cnt <= 7'd0;
                            p_sum <= 14'sd0; l_sum <= 16'd0;
                            dtw_ready <= 1'b0;   // stale verdict cleared
                            dtw_ready <= 1'b0;   // verdict superseded
                        end
                        if (cap_cnt < 7'd96) begin
                            cap_mem[cap_cnt[6:0]] <= {pitch_q4[9:2], level};
                            p_sum <= p_sum + $signed(pitch_q4[9:2]);
                            l_sum <= l_sum + {8'd0, level};
                            cap_cnt <= cap_cnt + 1'b1;
                        end
                    end else if (cap_active) begin
                        uv_cnt <= uv_cnt + 1'b1;
                        if (uv_cnt + 1'b1 >= UV_RESET) begin
                            cap_active <= 1'b0;
                            if (cap_cnt >= 7'd8) begin
                                st <= S_DIV;
                                // R81 lesson: best_cost/best_tpl MUST be
                                // reset per utterance -- the first test left
                                // best_cost=30 and every subsequent utterance
                                // compared against that stale minimum
                                best_cost <= 18'sd131071;
                                best_tpl <= 2'd0;
                                div_level <= 1'b0;
                                div_neg <= p_sum[13];
                                // R81 lesson: ~{2'b00, p_sum}+1 computes
                                // the complement of the ZERO-EXTENDED
                                // 16-bit pattern, not of the 14-bit value
                                // (|-1619| came out as 9933 instead of
                                // 1619). Negate in the native width.
                                div_num <= p_sum[13] ? (0 - p_sum)
                                                     : {2'b00, p_sum};
                                div_cnt <= 5'd0;
                                rem <= 8'd0;
                                div_q <= 16'd0;
                            end
                            // too short: keep the previous verdict
                        end
                    end
                end
            end

            // ================= S_DIV: restoring division, 16 cycles =========
            // pitch: |p_sum| (14b) / cap_cnt; level: l_sum (16b) / cap_cnt.
            // MSB-first shift-subtract; quotient collects 16 bits.
            else if (st == S_DIV) begin
                // 16-cycle restoring division: rem(8b) <= {rem, num bit};
                // quotient bit = (shifted rem >= divisor); divisor <= 96
                // fits 7 bits + sign headroom in the 8th.
                if (div_cnt == 5'd16) begin
                    if (!div_level) begin
                        mean_p <= div_neg ? -{1'b0, div_q[7:0]}
                                          : {1'b0, div_q[7:0]};
                        div_level <= 1'b1;
                        div_num <= l_sum;
                        div_cnt <= 5'd0;
                        rem <= 8'd0;
                        div_q <= 16'd0;
                    end else begin
                        mean_l <= div_q[7:0];
                        st <= S_RSM;
                        rs_j <= 6'd0;
                    end
                end else begin
                    rem_shift = {rem[6:0], div_num[15 - div_cnt[3:0]]};
                    if (rem_shift >= {1'b0, cap_cnt[6:0]}) begin
                        rem <= rem_shift - {1'b0, cap_cnt[6:0]};
                        div_q <= {div_q[14:0], 1'b1};
                    end else begin
                        rem <= rem_shift[6:0];
                        div_q <= {div_q[14:0], 1'b0};
                    end
                    div_cnt <= div_cnt + 1'b1;
                end
            end

            // ================= S_RSM =================
            else if (st == S_RSM) begin
                // nearest source frame = (rs_j * cap_cnt) >> 5; a 5x7-bit
                // multiply is one small DSP/LUT block -- far simpler than
                // the Bresenham variant, which needs up to 3 advances per
                // output frame when cap_cnt > 64
                work_p[rs_j] <= $signed(cap_mem[rs_src_idx[6:0]][15:8])
                                - mean_p;   // SIGNED: part-select [7:0] is
                                            // unsigned and broke negative
                                            // means (R81 lesson)
                // +128: the template level is stored bias-adjusted
                // (deviation + 128, docs/10 §6), so the resampled contour
                // must live in the same domain or every DP cell costs 128
                work_l[rs_j] <= cap_mem[rs_src_idx[6:0]][7:0] - mean_l[7:0]
                                + 8'd128;
                rs_j <= rs_j + 1'b1;
                if (rs_j == 6'd31) begin
                    st <= S_DTW;
                    tp_sel <= 2'd0;
                    row <= 6'd0; col <= 6'd0;
                    rowB_is_cur <= 1'b1;
                    cur <= 18'sd0;
                end
            end

            // ================= S_DTW =================
            else if (st == S_DTW) begin
                // write the cell value into the CURRENT-row array
                if (rowB_is_cur) rowB[col] <= d_cell;
                else             rowA[col] <= d_cell;
                cur <= d_cell;
                if (col == 6'd31) begin
                    // row finished
                    if (row == 6'd31) begin
                        // template cost = last cell of the last row
                        cost[tp_sel] <= d_cell;
                        if (d_cell < best_cost) begin
                            best_cost <= d_cell;
                            best_tpl  <= tp_sel;
                        end
                        row <= 6'd0;
                        col <= 6'd0;
                        rowB_is_cur <= 1'b1;      // fresh row 0
                        cur <= 18'sd0;
                        if (tp_sel == 2'd3) begin
                            st <= S_DONE;
                            // R81 lesson: best_tpl <= tp_sel is a
                            // non-blocking assignment on THIS clock;
                            // reading it here gives the PREVIOUS
                            // template's index. Compare d_cell against
                            // best_cost to include the last template.
                            if (d_cell < best_cost)
                                dtw_tone <= {1'b0, tp_sel} + 3'd1;
                            else
                                dtw_tone <= {1'b0, best_tpl} + 3'd1;
                            dtw_ready <= 1'b1;
                        end else begin
                            tp_sel <= tp_sel + 1'b1;
                        end
                    end else begin
                        row <= row + 1'b1;
                        col <= 6'd0;
                        rowB_is_cur <= ~rowB_is_cur;  // swap rows
                        cur <= 18'sd0;
                    end
                end else begin
                    col <= col + 1'b1;
                end
            end

            // ================= S_DONE =================
            else if (st == S_DONE) begin
                st <= S_CAP;                  // verdict held; S_CAP handles
                cap_cnt <= 7'd0;              //   the next capture's reset
                p_sum <= 14'sd0; l_sum <= 16'd0;
            end
        end
    end
endmodule
